    vector<int> q;
    q.reserve(n * m);

    for (int r = 0; r < n; ++r) {
        for (int c = 0; c < m; ++c) {
            if (grid[r][c] == 'S') {
                int id = r * m + c;
                dist[id] = 0;
                q.push_back(id);
            }
        }
    }

    const int dr[4] = {-1, 1, 0, 0};
    const int dc[4] = {0, 0, -1, 1};

