        int r = u / m;
        int c = u % m;
        int nd = dist[u] + 1;
        for (int d = 0; d < 4; ++d) {
            int nr = r + dr[d];
            int nc = c + dc[d];
            if (nr < 0 || nr >= n || nc < 0 || nc >= m) continue;
            if (grid[nr][nc] != '.') continue;
            int v = nr * m + nc;
            if (dist[v] == -1) {
                dist[v] = nd;
                q.push_back(v);
            }
        }
    }

    int maxDist = -1;
    int unreachable = 0;
    for (int r = 0; r < n; ++r) {
        for (int c = 0; c < m; ++c) {
            if (grid[r][c] == '.') {
                int d = dist[r * m + c];
                if (d == -1) {
                    ++unreachable;
                } else if (d > maxDist) {
                    maxDist = d;
                }
            }
        }
    }

    cout << maxDist << ' ' << unreachable << '\n';
    return 0;
