    dist = [-1] * total
    dq = deque()

    for idx, ch in enumerate(flat):
        if ch == "S":
            dist[idx] = 0
            dq.append(idx)

    while dq:
        u = dq.popleft()
        nd = dist[u] + 1
        r, c = divmod(u, m)
        if r > 0:
            v = u - m
            if flat[v] == "." and dist[v] == -1:
                dist[v] = nd
                dq.append(v)
        if r + 1 < n:
            v = u + m
            if flat[v] == "." and dist[v] == -1:
                dist[v] = nd
                dq.append(v)
        if c > 0:
            v = u - 1
            if flat[v] == "." and dist[v] == -1:
                dist[v] = nd
                dq.append(v)
        if c + 1 < m:
            v = u + 1
            if flat[v] == "." and dist[v] == -1:
                dist[v] = nd
                dq.append(v)

    max_dist = -1
    unreach = 0
    for idx, ch in enumerate(flat):
