    struct Frame {
        int u, idx;
    };
    vector<Frame> dfsStack;
    int timer = 0;
    int sccCount = 0;
    vector<long long> sccCoin(1, 0);

    for (int root = 1; root <= n; ++root) {
        if (tin[root]) continue;
        tin[root] = low[root] = ++timer;
        onStack[root] = 1;
        sccStack.push_back(root);
        dfsStack.push_back({root, 0});

        while (!dfsStack.empty()) {
            Frame& top = dfsStack.back();
            int u = top.u;
            if (top.idx < static_cast<int>(adj[u].size())) {
                int v = adj[u][top.idx++];
                if (!tin[v]) {
                    tin[v] = low[v] = ++timer;
                    onStack[v] = 1;
                    sccStack.push_back(v);
                    dfsStack.push_back({v, 0});
                } else if (onStack[v]) {
                    if (tin[v] < low[u]) low[u] = tin[v];
                }
            } else {
                dfsStack.pop_back();
                if (!dfsStack.empty()) {
                    int p = dfsStack.back().u;
                    if (low[u] < low[p]) low[p] = low[u];
                }
                if (low[u] == tin[u]) {
                    ++sccCount;
                    long long total = 0;
                    while (true) {
                        int w = sccStack.back();
                        sccStack.pop_back();
                        onStack[w] = 0;
                        comp[w] = sccCount;
                        total += coins[w];
                        if (w == u) break;
                    }
                    sccCoin.push_back(total);
                }
            }
        }
    }

    vector<vector<int>> dag(sccCount + 1);
    for (int u = 1; u <= n; ++u) {
        int cu = comp[u];
        for (int v : adj[u]) {
            int cv = comp[v];
            if (cu != cv) {
                dag[cu].push_back(cv);
            }
        }
